package com.example.preview;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

/**
 * Configuration value object for preview feature.
 * Values can be overridden via application.properties / environment variables.
 */
@Component
@ConfigurationProperties(prefix = "preview")
public class PreviewConfig {

    /** Maximum milliseconds to wait for the external metadata fetch */
    private long fetchTimeoutMs = 3000;

    /** Maximum milliseconds to wait for overall preview retrieval (cache + fetch) */
    private long cacheTimeoutMs = 3000;

    /** How long to keep a preview document in the cache, in seconds */
    private long cacheTtlSeconds = 86400;

    /** Maximum number of HTTP redirects to follow during metadata fetch */
    private int maxRedirects = 5;

    public long getFetchTimeoutMs() {
        return fetchTimeoutMs;
    }

    public void setFetchTimeoutMs(long fetchTimeoutMs) {
        this.fetchTimeoutMs = fetchTimeoutMs;
    }

    public long getCacheTimeoutMs() {
        return cacheTimeoutMs;
    }

    public void setCacheTimeoutMs(long cacheTimeoutMs) {
        this.cacheTimeoutMs = cacheTimeoutMs;
    }

    public long getCacheTtlSeconds() {
        return cacheTtlSeconds;
    }

    public void setCacheTtlSeconds(long cacheTtlSeconds) {
        this.cacheTtlSeconds = cacheTtlSeconds;
    }

    public int getMaxRedirects() {
        return maxRedirects;
    }

    public void setMaxRedirects(int maxRedirects) {
        this.maxRedirects = maxRedirects;
    }
}
