package com.example.preview;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonProperty;

import java.time.Instant;

/**
 * Value object / entity holding all preview metadata for a short code.
 */
@JsonInclude(JsonInclude.Include.ALWAYS)
public class PreviewDocument {

    @JsonProperty("shortCode")
    private String shortCode;

    @JsonProperty("targetUrl")
    private String targetUrl;

    @JsonProperty("title")
    private String title;

    @JsonProperty("description")
    private String description;

    @JsonProperty("fetchedAt")
    private String fetchedAt;

    @JsonProperty("cacheExpiresAt")
    private String cacheExpiresAt;

    /** Whether this document is stale (past cacheExpiresAt but returned anyway) */
    @JsonProperty("stale")
    private boolean stale;

    public PreviewDocument() {
    }

    public PreviewDocument(String shortCode,
                           String targetUrl,
                           String title,
                           String description,
                           String fetchedAt,
                           String cacheExpiresAt) {
        this.shortCode = shortCode;
        this.targetUrl = targetUrl;
        this.title = title;
        this.description = description;
        this.fetchedAt = fetchedAt;
        this.cacheExpiresAt = cacheExpiresAt;
        this.stale = false;
    }

    public boolean isExpired() {
        if (cacheExpiresAt == null) return true;
        try {
            return Instant.parse(cacheExpiresAt).isBefore(Instant.now());
        } catch (Exception e) {
            return true;
        }
    }

    // --- Getters & Setters ---

    public String getShortCode() {
        return shortCode;
    }

    public void setShortCode(String shortCode) {
        this.shortCode = shortCode;
    }

    public String getTargetUrl() {
        return targetUrl;
    }

    public void setTargetUrl(String targetUrl) {
        this.targetUrl = targetUrl;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public String getFetchedAt() {
        return fetchedAt;
    }

    public void setFetchedAt(String fetchedAt) {
        this.fetchedAt = fetchedAt;
    }

    public String getCacheExpiresAt() {
        return cacheExpiresAt;
    }

    public void setCacheExpiresAt(String cacheExpiresAt) {
        this.cacheExpiresAt = cacheExpiresAt;
    }

    public boolean isStale() {
        return stale;
    }

    public void setStale(boolean stale) {
        this.stale = stale;
    }

    @Override
    public String toString() {
        return "PreviewDocument{" +
                "shortCode='" + shortCode + '\'' +
                ", targetUrl='" + targetUrl + '\'' +
                ", title='" + title + '\'' +
                ", description='" + description + '\'' +
                ", fetchedAt='" + fetchedAt + '\'' +
                ", cacheExpiresAt='" + cacheExpiresAt + '\'' +
                ", stale=" + stale +
                '}';
    }
}
