package com.example.preview;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

import java.time.Duration;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Read/write abstraction over a Redis store (with an in-process ConcurrentHashMap fallback).
 * Keys have the form: preview:{code}
 * Values are JSON-serialised PreviewDocument objects.
 * Uses SET NX (setIfAbsent) for first write to prevent cache stampede.
 */
@Component
public class PreviewCache {

    private static final Logger log = LoggerFactory.getLogger(PreviewCache.class);
    private static final String KEY_PREFIX = "preview:";

    private final ObjectMapper objectMapper;
    private final PreviewConfig config;

    // Optional Redis template — may be null if Redis is not configured
    private final StringRedisTemplate redisTemplate;

    // In-process fallback cache
    private final ConcurrentHashMap<String, String> localCache = new ConcurrentHashMap<>();

    public PreviewCache(ObjectMapper objectMapper,
                        PreviewConfig config,
                        @org.springframework.lang.Nullable StringRedisTemplate redisTemplate) {
        this.objectMapper = objectMapper;
        this.config = config;
        this.redisTemplate = redisTemplate;
    }

    /**
     * Retrieve a cached PreviewDocument for the given short code.
     *
     * @param code the short code
     * @return Optional containing the document if found, empty otherwise
     */
    public Optional<PreviewDocument> get(String code) {
        String key = buildKey(code);
        String json = readFromStore(key);
        if (json == null) {
            return Optional.empty();
        }
        try {
            PreviewDocument doc = objectMapper.readValue(json, PreviewDocument.class);
            return Optional.of(doc);
        } catch (JsonProcessingException e) {
            log.warn("Failed to deserialize cached preview for code '{}': {}", code, e.getMessage());
            return Optional.empty();
        }
    }

    /**
     * Write a PreviewDocument to the cache.
     * Uses atomic SET NX (set-if-absent) for the first write to prevent stampede.
     * Subsequent writes (updates/refreshes) overwrite unconditionally.
     *
     * @param doc the document to store
     */
    public void put(PreviewDocument doc) {
        String key = buildKey(doc.getShortCode());
        String json;
        try {
            json = objectMapper.writeValueAsString(doc);
        } catch (JsonProcessingException e) {
            log.error("Failed to serialize PreviewDocument for code '{}': {}", doc.getShortCode(), e.getMessage());
            return;
        }
        Duration ttl = Duration.ofSeconds(config.getCacheTtlSeconds());
        writeToStore(key, json, ttl);
    }

    /**
     * Attempt a first-write using SET NX semantics; returns true if the value was written.
     * Falls through to a normal put if NX fails (key already exists), preventing stampede
     * while still allowing refreshes.
     */
    public boolean putIfAbsent(PreviewDocument doc) {
        String key = buildKey(doc.getShortCode());
        String json;
        try {
            json = objectMapper.writeValueAsString(doc);
        } catch (JsonProcessingException e) {
            log.error("Failed to serialize PreviewDocument for code '{}': {}", doc.getShortCode(), e.getMessage());
            return false;
        }
        Duration ttl = Duration.ofSeconds(config.getCacheTtlSeconds());
        return writeIfAbsentToStore(key, json, ttl);
    }

    /**
     * Evict the cache entry for a given short code.
     */
    public void evict(String code) {
        String key = buildKey(code);
        if (redisTemplate != null) {
            try {
                redisTemplate.delete(key);
                return;
            } catch (Exception e) {
                log.warn("Redis evict failed for key '{}', falling back to local cache: {}", key, e.getMessage());
            }
        }
        localCache.remove(key);
    }

    // --- Private helpers ---

    private String buildKey(String code) {
        return KEY_PREFIX + code;
    }

    private String readFromStore(String key) {
        if (redisTemplate != null) {
            try {
                return redisTemplate.opsForValue().get(key);
            } catch (Exception e) {
                log.warn("Redis read failed for key '{}', falling back to local cache: {}", key, e.getMessage());
            }
        }
        return localCache.get(key);
    }

    private void writeToStore(String key, String json, Duration ttl) {
        if (redisTemplate != null) {
            try {
                redisTemplate.opsForValue().set(key, json, ttl);
                return;
            } catch (Exception e) {
                log.warn("Redis write failed for key '{}', falling back to local cache: {}", key, e.getMessage());
            }
        }
        // Local fallback (no TTL enforcement in-process — acceptable for dev/test)
        localCache.put(key, json);
    }

    private boolean writeIfAbsentToStore(String key, String json, Duration ttl) {
        if (redisTemplate != null) {
            try {
                Boolean result = redisTemplate.opsForValue().setIfAbsent(key, json, ttl);
                return Boolean.TRUE.equals(result);
            } catch (Exception e) {
                log.warn("Redis setIfAbsent failed for key '{}', falling back to local cache: {}", key, e.getMessage());
            }
        }
        // ConcurrentHashMap.putIfAbsent returns null when the key was absent (i.e., we wrote it)
        return localCache.putIfAbsent(key, json) == null;
    }
}
